const FOOD_TRANSLATIONS: Record<string, FoodTranslation> = { ...FOOD_WORDS, ...FOOD_WORDS_EXTRA };

function localizeFoodName(value: string, language: LanguageCode): string {
  if (language === 'fr') return value;
  return Object.keys(FOOD_TRANSLATIONS).sort((a, b) => b.length - a.length).reduce((result, word) => {
    const replacement = FOOD_TRANSLATIONS[word][language];
    if (!replacement) return result;
    const escapedWord = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return result.replace(new RegExp(`(^|[\\s,;:()\\-])${escapedWord}(?=$|[\\s,;:()\\-])`, 'gi'), (_match, prefix: string) => `${prefix}${replacement}`);
  }, value);
}

function detectLanguage(): LanguageCode {
  try {
    const locale = Intl.DateTimeFormat().resolvedOptions().locale.toLowerCase();
    return LANGUAGES.find((item) => locale.startsWith(item.code))?.code || FALLBACK;
  } catch {
    return FALLBACK;
  }
}

interface I18nValue {
  language: LanguageCode;
  locale: string;
  ready: boolean;
  languageChosen: boolean;
  languages: LanguageOption[];
  setLanguage: (language: LanguageCode) => void;
  t: (key: string) => string;
  categoryLabel: (category: string) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: Date | string, options?: Intl.DateTimeFormatOptions) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<LanguageCode>(detectLanguage());
  const [languageChosen, setLanguageChosen] = useState(false);
  const [ready, setReady] = useState(false);
  const locale = LANGUAGES.find((item) => item.code === language)?.locale || 'fr-FR';

  useEffect(() => {
    AsyncStorage.getItem(STORAGE_KEY).then((value) => {
      if (value && LANGUAGES.some((item) => item.code === value)) {
        setLanguageState(value as LanguageCode);
        setLanguageChosen(true);
      }
    }).catch(() => {}).finally(() => setReady(true));
  }, []);

  const setLanguage = useCallback((next: LanguageCode) => {
    setLanguageState(next);
    setLanguageChosen(true);
    void AsyncStorage.setItem(STORAGE_KEY, next).catch(() => {});
  }, []);

  const t = useCallback((key: string) => {
    const resolvedKey = RAW_ALIASES[key] || key;
    return DICTIONARIES[language][resolvedKey] || EN[resolvedKey] || FR[resolvedKey] || localizeFoodName(key, language);
  }, [language]);

  const categoryLabel = useCallback((category: string) => t(`categories.${category}`), [t]);
  const formatNumber = useCallback((value: number, options?: Intl.NumberFormatOptions) => new Intl.NumberFormat(locale, options).format(value), [locale]);
  const formatDate = useCallback((value: Date | string, options?: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat(locale, options).format(typeof value === 'string' ? new Date(value) : value), [locale]);
  const value = useMemo(() => ({ language, locale, ready, languageChosen, languages: LANGUAGES, setLanguage, t, categoryLabel, formatNumber, formatDate }), [language, locale, ready, languageChosen, setLanguage, t, categoryLabel, formatNumber, formatDate]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used within I18nProvider');
  return value;
}
